from __future__ import annotations


import pytest

from ansible.modules.unarchive import ZipArchive, TgzArchive


@pytest.fixture
def fake_ansible_module():
    return FakeAnsibleModule()


class FakeAnsibleModule:
    def __init__(self):
        self.params = {}
        self.tmpdir = None


class TestCaseZipArchive:
    @pytest.mark.parametrize('timestamp, expected', (
        ('19800101.000000', (1980, 1, 1, 0, 0, 0)),
        ('21071231.235958', (2107, 12, 31, 23, 59, 58)),
        ('20000229.123456', (2000, 2, 29, 12, 34, 56)),
    ))
    def test_valid_time_stamp(self, timestamp, expected):
        result = ZipArchive._valid_time_stamp(None, timestamp)
        assert result[:6] == expected

    @pytest.mark.parametrize('timestamp', (
        '19800000.000000',
        '19791231.235958',
        '21080101.000000',
        '20010229.000000',
        '19801301.000000',
        '19800101.246000',
        '19800101.000000extra',
        'not-a-timestamp',
    ))
    def test_invalid_time_stamp(self, timestamp):
        assert ZipArchive._valid_time_stamp(None, timestamp) == (1980, 1, 1, 0, 0, 0, 0, 0, 0)

    def test_existing_file_with_invalid_time_stamp(self, tmp_path, fake_ansible_module, mocker):
        (tmp_path / 'entry.txt').write_text('data')
        fake_ansible_module.params = {
            'extra_opts': [],
            'exclude': [],
            'include': [],
            'io_buffer_size': 65536,
            'keep_newer': False,
        }
        fake_ansible_module.run_command = lambda cmd: (
            0, '-rw-r--r--  3.0 unx  4 tx defN 19800000.000000 entry.txt\n', ''
        )
        fake_ansible_module.debug = lambda message: None
        archive = ZipArchive('', bytes(tmp_path), {'owner': None, 'group': None, 'mode': None}, fake_ansible_module)
        mocker.patch.object(archive, '_crc32', return_value=0)

        result = archive.is_unarchived()

        assert result['unarchived'] is False
        assert 'entry.txt' in archive.includes

    @pytest.mark.parametrize(
        'side_effect, expected_reason', (
            ([ValueError, '/bin/zipinfo'], "Unable to find required 'unzip'"),
            (ValueError, "Unable to find required 'unzip' or 'zipinfo'"),
        )
    )
    def test_no_zip_zipinfo_binary(self, mocker, fake_ansible_module, side_effect, expected_reason):
        mocker.patch("ansible.modules.unarchive.get_bin_path", side_effect=side_effect)
        fake_ansible_module.params = {
            "extra_opts": "",
            "exclude": "",
            "include": "",
            "io_buffer_size": 65536,
        }

        z = ZipArchive(
            src="",
            b_dest="",
            file_args="",
            module=fake_ansible_module,
        )
        can_handle, reason = z.can_handle_archive()

        assert can_handle is False
        assert expected_reason in reason
        assert z.cmd_path is None


class TestCaseTgzArchive:
    def test_no_tar_binary(self, mocker, fake_ansible_module):
        mocker.patch("ansible.modules.unarchive.get_bin_path", side_effect=ValueError)
        fake_ansible_module.params = {
            "extra_opts": "",
            "exclude": "",
            "include": "",
            "io_buffer_size": 65536,
        }
        fake_ansible_module.check_mode = False

        t = TgzArchive(
            src="",
            b_dest="",
            file_args="",
            module=fake_ansible_module,
        )
        can_handle, reason = t.can_handle_archive()

        assert can_handle is False
        assert 'Unable to find required' in reason
        assert t.cmd_path is None
        assert t.tar_type is None
